// Simple Asteroid Dodge game based on IDEA.md
// Assumes there is a <canvas id="game"></canvas> in the HTML.

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');

  // Set canvas size (fallback to 800x600 if not styled)
  canvas.width = canvas.clientWidth || 800;
  canvas.height = canvas.clientHeight || 600;

  // Ship definition
  const ship = {
    x: canvas.width / 2,
    y: canvas.height - 50,
    radius: 15,
    speed: 5,
    color: '#00ff00',
    dx: 0,
    dy: 0,
    update() {
      this.x += this.dx;
      this.y += this.dy;
      // Keep within bounds
      this.x = Math.max(this.radius, Math.min(canvas.width - this.radius, this.x));
      this.y = Math.max(this.radius, Math.min(canvas.height - this.radius, this.y));
    },
    draw() {
      ctx.fillStyle = this.color;
      ctx.beginPath();
      ctx.moveTo(this.x, this.y - this.radius);
      ctx.lineTo(this.x - this.radius, this.y + this.radius);
      ctx.lineTo(this.x + this.radius, this.y + this.radius);
      ctx.closePath();
      ctx.fill();
    },
  };

  // Asteroid definition
  const asteroids = [];
  let asteroidSpawnInterval = 2000; // ms
  let lastSpawn = 0;
  let asteroidSpeed = 2;

  function spawnAsteroid() {
    const radius = 20 + Math.random() * 20;
    const x = Math.random() * (canvas.width - 2 * radius) + radius;
    const y = -radius;
    asteroids.push({ x, y, radius, speed: asteroidSpeed, color: '#888' });
  }

  function updateAsteroids(delta) {
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.y += a.speed;
      // remove off‑screen
      if (a.y - a.radius > canvas.height) asteroids.splice(i, 1);
    }
    // increase difficulty over time
    asteroidSpeed = Math.min(12, asteroidSpeed + delta * 0.00001);
  }

  function drawAsteroids() {
    ctx.fillStyle = '#888';
    asteroids.forEach(a => {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
      ctx.fill();
    });
  }

  function checkCollision() {
    for (const a of asteroids) {
      const dx = a.x - ship.x;
      const dy = a.y - ship.y;
      const dist = Math.hypot(dx, dy);
      if (dist < a.radius + ship.radius) {
        return true;
      }
    }
    return false;
  }

  let lastTime = performance.now();
  let gameOver = false;

  function loop(timestamp) {
    const delta = timestamp - lastTime;
    lastTime = timestamp;

    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#fff';
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
      return;
    }

    // spawn logic
    if (timestamp - lastSpawn > asteroidSpawnInterval) {
      spawnAsteroid();
      lastSpawn = timestamp;
      // gradually speed up spawning
      asteroidSpawnInterval = Math.max(500, asteroidSpawnInterval - 20);
    }

    // Update entities
    ship.update();
    updateAsteroids(delta);

    // Check collisions
    if (checkCollision()) {
      gameOver = true;
    }

    // Render
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ship.draw();
    drawAsteroids();

    requestAnimationFrame(loop);
  }

  // Input handling (arrow keys)
  const keys = {};
  window.addEventListener('keydown', e => {
    keys[e.key] = true;
    updateDirection();
  });
  window.addEventListener('keyup', e => {
    keys[e.key] = false;
    updateDirection();
  });

  function updateDirection() {
    ship.dx = 0;
    ship.dy = 0;
    if (keys['ArrowLeft']) ship.dx = -ship.speed;
    if (keys['ArrowRight']) ship.dx = ship.speed;
    if (keys['ArrowUp']) ship.dy = -ship.speed;
    if (keys['ArrowDown']) ship.dy = ship.speed;
  }

  // Start the loop
  requestAnimationFrame(loop);
})();
